id: code:zapamcom10100.c:b200_SMS_transfer
signature: static long b200_SMS_transfer (zapamcom10100_io_t *itf)

function body:
```
static long
b200_SMS_transfer   (zapamcom10100_io_t *itf)
{
    long rc = RC_NRM;
    char lc_tmpconv[LEN_ZAPAMCOM10100_IN_BANK_CARD_NUM + 1];         /* masking 처리를 위한 변수 */

    /* 전송시작일시   */
    char lc_trms_sta_dt_hms  [LEN_GET_DATE_TIME            +1];
    char c_mms_phrs          [LEN_ZORDMS0100023_MSG_CTT_I  +1];      /* 20081201A */
    char c_sms_phrs          [LEN_ZORDMS0100023_MSG_CTT_I  +1];      /* 20081201A */

    zngmmmsg12310_io_t          zngmmmsg12310_io;
    zordms0100023_io_t          zordms0100023_io;                     /* MMS/SMS 전송 메세지 Commbuff Set 모듈 (20081201A) */

    memset( &zngmmmsg12310_io, 0x00, sizeof( zngmmmsg12310_io_t ) );
      /* Input으로 입력된 파라미터값을 SMS I/F발송 API 구조체로 setting */

    memset( &zordms0100023_io, 0x00, sizeof( zordms0100023_io_t ) );   /* 20081201A */
    memset( c_sms_phrs          , 0x00, LEN_ZORDMS0100023_MSG_CTT_I ); /* 20081201A */
    memset( c_mms_phrs          , 0x00, LEN_ZORDMS0100023_MSG_CTT_I ); /* 20081201A */
    memset(lc_trms_sta_dt_hms, 0x00, LEN_GET_DATE_TIME );

    strncpy( zngmmmsg12310_io.in.pgm_id, itf->in.pgm_id, LEN_ZNGMMMSG12310_IN_PGM_ID );

     /*******************************************************************************
     *sms_phrs 메시지부는 실제로 token(#1 #2) 의 token mapping 이며
     * 구분자(|)이다 그래서 ex데이타는 은행/카드사명|은행/카드번호 로 이뤄줘야 한다.
     * ******************************************************************************/

    /* space제거작업 */
    mpfm_trim(itf->in.bank_card_co_cd_nm);
    mpfm_trim(itf->in.bank_card_num);


    /****************************************************
     * 주의!! 20060529 추가
     * 아래의 로직은 은행/카드사번호의 Masking처리를 위한
     * 로직이 반영됨으로 아래와 같이 처리하며 향후 CCA등의
     * 공통모듈이 추가되면 이를 모듈로 대체하면 될듯 현재
     * 관련 모듈이 없어 아래의 로직을 구현함
     * *************************************************/
    //  '*'  로 먼저 셋팅초기화
    memset(lc_tmpconv ,  0x2a, LEN_ZAPAMCOM10100_IN_BANK_CARD_NUM );

    /*
    *  LEN_ZAPAMCOM10100_IN_CONV_KOUNT은 현재 4로 되어있으며 만약
    *  위의 선언부에서 해당매크로 상수만 수치만 수정하시면 적용됩니다.
    *  결과 예시: 9612*************** 로 결과가 되어 전송됩니다.
    *  마스캉 처리규칙
    *  카드일때 : 000000**
    *  은행일때 : 0000**  */

    //20060710 수정함 은행과 카드를 별도처리하여야 한다
    if ( strncmp(itf->in.pay_mthd_cd, "02", LEN_ZAPAMCOM10100_IN_PAY_MTHD_CD ) == RC_NRM )
    {

        //#define LEN_ZAPAMCOM10100_IN_BANK_OFFSET 6
        //#define LEN_ZAPAMCOM10100_IN_CARD_OFFSET 8

        strncpy(lc_tmpconv, itf->in.bank_card_num, LEN_ZAPAMCOM10100_IN_CONV_CD_KOUNT);
        lc_tmpconv[LEN_ZAPAMCOM10100_IN_CARD_OFFSET] = 0x00;
    } else
    {
        //은행의 경우 0000**
        strncpy(lc_tmpconv, itf->in.bank_card_num, LEN_ZAPAMCOM10100_IN_CONV_KOUNT);
        lc_tmpconv[LEN_ZAPAMCOM10100_IN_BANK_OFFSET] = 0x00;
    }

    PFM_DBG("bank_card_num Conv reault [%s]!!!!", lc_tmpconv);

    //20060529 itf->in.bank_card_num ---> lc_tmpconv로 수정함
    //snprintf(zngmmmsg12310_io.in.sms_phrs, LEN_ZNGMMMSG12310_IN_SMS_PHRS, "%s|%s|",
    //                                       itf->in.bank_card_co_cd_nm, lc_tmpconv);

    /* tmplt_id는 아직 미구현 상태다 현재는 APACRT001 이므로. */
    /***********************************************************
     * 신청구분 및 납부방법에 따른 instance가 별도 처리 됨으로
     * 인해 추가함 20060704
     * *********************************************************/
   // strncpy( zngmmmsg12310_io.in.tmplt_id, itf->in.tmplt_id, LEN_ZNGMMMSG12310_IN_TMPLT_ID );

    /*2018.12.06  AS-IS : 인출예정일자 구하여  존재시 APACRT025    미존재시 : APACRT012, APACRT015 로 전송
                  TO-BE : ap_req_typ_cd='R' (신규) 이면 APACRT025    'C'(변경): APACRT012, APACRT015 로 전송
        이유] AS-IS : zapamcom20010.인출예정일자  구분:신청 => 예정일자존재.   구분:변경 => 예정일자미존재로 return되었음
              TO-BE : 수정되는 zapamcom20010.최초인출예정일자는 신청.변경 모두 인출일자값 return 됨.
              ==>  zapamcom20010.최초인출예정일자 존재유무로 판단하는것을 ap_req_typ_cd 로 대체함
    */
    PFM_DSP ( "[b200_SMS_transfer] req_cl_cd=[%s] itf->in.ap_req_typ_cd=[%s] rcv_phon_num=[%s]" ,itf->in.req_cl_cd, itf->in.ap_req_typ_cd, itf->in.rcv_phon_num ) ;
    // 2018.12.06 ap_req_typ_cd default = 'C' 로 세팅
    if ( mpfm_isspnull(itf->in.ap_req_typ_cd) == RC_NRM  || strlen( mpfm_trim(itf->in.ap_req_typ_cd )) == 0 )
    {
        itf->in.ap_req_typ_cd[0] = 'C' ;
    }

    if ((itf->in.req_cl_cd[RC_NRM] == '1') ||  // 신청
        (itf->in.req_cl_cd[RC_NRM] == '6') ||  // 실시간은행원장등록 자동납부신청
        (itf->in.req_cl_cd[RC_NRM] == '9'))  // 개통모듈-신청
    {

        if ( strncmp(itf->in.pay_mthd_cd, "05", LEN_ZAPAMCOM10100_IN_PAY_MTHD_CD ) == RC_NRM )
        { //간편결제

            /*  처리결과 정상인 경우 SMS전문 */
            strncpy( zngmmmsg12310_io.in.tmplt_id, "APACRT018", LEN_ZNGMMMSG12310_IN_TMPLT_ID );
            snprintf(zngmmmsg12310_io.in.sms_phrs, LEN_ZNGMMMSG12310_IN_SMS_PHRS, "%s|%s|",
                                                     itf->in.bank_card_co_cd_nm /* #01  간편결제사명   */
                                                   , gc_cust_nm  );             /* #02  고객명         */
        }
        else
        { //은행 or 카드
            /* 2018.12.06 인출예정일자로 구분하던것을 ap_req_typ_cd 로 대체 */
             //if( strlen(gc_drw_dt) == (size_t)1 )
             if ( itf->in.ap_req_typ_cd[0] == 'C' )
             {
                if (itf->in.bank_prt_yn[RC_NRM] == 'Y' )
                 {
                    /*  자동납부  '카드'  신청, 계좌인쇄여부 'Y'인 경우 SMS전문 */
                    strncpy( zngmmmsg12310_io.in.tmplt_id, "APACRT012", LEN_ZNGMMMSG12310_IN_TMPLT_ID );
                    snprintf(zngmmmsg12310_io.in.sms_phrs, LEN_ZNGMMMSG12310_IN_SMS_PHRS, "%s|%s|%s|",
                                                             itf->in.bank_card_co_cd_nm
                                                           , lc_tmpconv
                                                           , gc_cust_nm                /* #03  고객명  : 2018.12.06  */
                                                            );
                 }
                 else
                 {
                    /*  자동납부  '카드' 신청, 계좌인쇄여부 'N'인 경우 SMS전문 */
                    strncpy( zngmmmsg12310_io.in.tmplt_id, "APACRT015", LEN_ZNGMMMSG12310_IN_TMPLT_ID );
                    snprintf(zngmmmsg12310_io.in.sms_phrs, LEN_ZNGMMMSG12310_IN_SMS_PHRS, "%s|%s|",
                                                             itf->in.bank_card_co_cd_nm
                                                           , gc_cust_nm              /* #03  고객명  : 2018.12.06  */
                                                            );
                 }

                 if (itf->in.req_cl_cd[RC_NRM] == '9')     // 개통모듈-신청
                 {
                       /* 전송 시작시각 구하기 */
                       rc = mpfm_get_date_calc_time( gc_get_date_time , 720 , lc_trms_sta_dt_hms );   //12분후에 SMS발송
                       if (rc !=RC_NRM)
                       {
                           PFM_MSGE(T_S, "ZNGME0000", "%T%s", "&TEST", "날자 계산 조회" );
                           PFM_ERRS("mpfm_get_date_calc_time( ) ERROR!! rc[%ld]", rc);
                           return RC_ERR;
                       }

                       /* 전송시작일시 */
                       strncpy( zngmmmsg12310_io.in.trms_sta_dt_hms    , lc_trms_sta_dt_hms
                                   , LEN_ZNGMMMSG12310_IN_TRMS_STA_DT_HMS );

                 }
             }
             /* 2009.05.18 */
             else
             {
                  /* 예금주명 조회  20101216 */
                  PFM_TRYNJ( b550_select_ownr_nm(itf));
                  if (rc != RC_NRM)
                  {
                        /* SMS송신 중 오류라도 정상 종료처리함.  */
                  }
                  /* space제거작업 */
                  mpfm_trim(gc_ownr_nm);
                  /* gc_drw_dt <- 값 조회 시 auto_pay_req_cl_cd 'R' 을 체크 하므로
                   * .req_cl_cd[RC_NRM] == '1' 신청/변경 동일 하지만 신경 쓰지 않는다. */
                 //  strncpy( zngmmmsg12310_io.in.tmplt_id, "APACRT023", LEN_ZNGMMMSG12310_IN_TMPLT_ID );
                  strncpy( zngmmmsg12310_io.in.tmplt_id, "APACRT025", LEN_ZNGMMMSG12310_IN_TMPLT_ID );
                  snprintf(zngmmmsg12310_io.in.sms_phrs, LEN_ZNGMMMSG12310_IN_SMS_PHRS, "%s|%s|%s|%s|",
                                                         itf->in.bank_card_co_cd_nm
                                                       , gc_ownr_nm
                                                       , gc_drw_dt
                                                       , gc_cust_nm                /* #04  고객명  : 2018.12.06  */
                                                       );
             }

        }

    }
    /* 2009/01/13 추가 start : 신규가입일 경우에 MMS 전송처리 */
    else if (itf->in.req_cl_cd[RC_NRM] == '5')
    {
          rc = mpfm_get_date_calc_time( gc_get_date_time , 3720 , lc_trms_sta_dt_hms );   //62분후에 SMS발송

          if (rc !=RC_NRM)
          {
              PFM_MSGE(T_S, "ZNGME0000", "%T%s", "&TEST", "날자 계산 조회" );
              PFM_ERRS("mpfm_get_date_calc_time( ) ERROR!! rc[%ld]", rc);
              return RC_ERR;
          }
          /**************************************************************************************************
          [SMS]
              rcv_phone_num
              svc_mgmt_num
              msg_tmplt_id
              msg_ctt
              cb_num
              cb_url
              trms_sta_dt_hms
              timeout_tm
          [MMS]
              rcv_phone_num
              svc_mgmt_num
              svc_chg_cd
              msg_sect_cd
              msg_ctt
              cb_num
              cb_url
              mms_op_cl_cd
              trms_sta_dt_hms
              timeout_tm
          **************************************************************************************************/
          if (strncmp(gc_mms_psbl_yn,"Y", LEN_YN) == 0) // MMS 전송 가능
          {
              strncpy( zordms0100023_io.in.mms_yn, "Y"                                                               , LEN_ZORDMS0100023_MMS_YN_I        );  /* [MMS(Y), SMS(N) ] MMS/SMS 구분코드                           */
              strncpy( zordms0100023_io.in.rcv_phone_num  ,  itf->in.rcv_phon_num                                    , LEN_ZORDMS0100023_RCV_PHONE_NUM_I );  /* [ 공통          ] 수신전화번호                               */
              strncpy( zordms0100023_io.in.svc_chg_cd     , "A1"                                                     , LEN_ZORDMS0100023_SVC_CHG_CD_I    );  /* [ MMS 전용      ] 서비스변경코드                             */
              strncpy( zordms0100023_io.in.svc_mgmt_num   , ""                                                       , LEN_ZORDMS0100023_SVC_MGMT_NUM_I  );  /* [ 공통          ] 서비스관리번호                             */
              strncpy( zordms0100023_io.in.msg_tmplt_id   , ""                                                       , LEN_ZORDMS0100023_MSG_TMPLT_ID_I  );  /* [ SMS 전용      ] 메세지템플릿ID                             */

              if (itf->in.bank_prt_yn[RC_NRM] == 'Y' )
              {
                 snprintf(c_mms_phrs,LEN_ZORDMS0100023_MSG_CTT_I,"자동납부: %s%s", itf->in.bank_card_co_cd_nm, lc_tmpconv);    /* [ 공통          ] 메세지내용                                 */
              }
